WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY sale_date NULLS FIRST, id) AS dedup_rank FROM store_sales) t WHERE dedup_rank = 1) SELECT CASE WHEN revenue >= 3300 THEN 'LARGE' ELSE 'SMALL' END AS revenue_tier, APPROX_PERCENTILE(units, ARRAY(0.25, 0.5, 0.75)) AS units_quartiles, COUNT(DISTINCT store_id) AS distinct_store_ids, COUNT(*) AS num_rows, COUNT(*) AS event_count, PERCENTILE_APPROX(units, ARRAY(0.25, 0.5, 0.75)) AS units_quartiles_2, CORR(revenue, units) AS corr_revenue_units FROM latest GROUP BY 1 HAVING distinct_store_ids > 1
